CREATE TABLE `User` (`id` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,`email` VARCHAR(191) NOT NULL,`phone` VARCHAR(191) NOT NULL,`passwordHash` VARCHAR(191) NOT NULL,`role` ENUM('OFFICER', 'BIDDER') NOT NULL,`emailVerified` BOOLEAN NOT NULL DEFAULT false,`phoneVerified` BOOLEAN NOT NULL DEFAULT false,`isActive` BOOLEAN NOT NULL DEFAULT true,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `User_email_key`(`email`), UNIQUE INDEX `User_phone_key`(`phone`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `OfficerProfile` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`employeeId` VARCHAR(191) NOT NULL,`department` VARCHAR(191) NOT NULL,`designation` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `OfficerProfile_userId_key`(`userId`), UNIQUE INDEX `OfficerProfile_employeeId_key`(`employeeId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Company` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`companyName` VARCHAR(191) NOT NULL,`cin` VARCHAR(191) NULL,`pan` VARCHAR(191) NULL,`gstin` VARCHAR(191) NULL,`msmeNumber` VARCHAR(191) NULL,`address` VARCHAR(191) NULL,`city` VARCHAR(191) NULL,`state` VARCHAR(191) NULL,`pincode` VARCHAR(191) NULL,`contactEmail` VARCHAR(191) NULL,`contactPhone` VARCHAR(191) NULL,`status` ENUM('ACTIVE', 'BLACKLISTED') NOT NULL DEFAULT 'ACTIVE',`blacklistReason` VARCHAR(191) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Company_userId_key`(`userId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Tender` (`id` VARCHAR(191) NOT NULL,`tenderNumber` VARCHAR(191) NOT NULL,`title` VARCHAR(191) NOT NULL,`description` VARCHAR(191) NOT NULL,`category` VARCHAR(191) NOT NULL,`startDate` DATETIME(3) NOT NULL,`closingDate` DATETIME(3) NOT NULL,`status` ENUM('DRAFT', 'ACTIVE', 'CLOSED') NOT NULL DEFAULT 'DRAFT',`officerId` VARCHAR(191) NOT NULL,`documentUrl` VARCHAR(191) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Tender_tenderNumber_key`(`tenderNumber`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `TenderRequirement` (`id` VARCHAR(191) NOT NULL,`tenderId` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,`category` ENUM('STATUTORY', 'FINANCIAL', 'EXPERIENCE', 'TECHNICAL') NOT NULL,`required` BOOLEAN NOT NULL DEFAULT true,`description` VARCHAR(191) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `TenderRequirement_tenderId_idx`(`tenderId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Document` (`id` VARCHAR(191) NOT NULL,`companyId` VARCHAR(191) NOT NULL,`documentType` VARCHAR(191) NOT NULL,`fileName` VARCHAR(191) NOT NULL,`fileUrl` VARCHAR(191) NOT NULL,`status` ENUM('PENDING', 'VERIFIED', 'REVIEW', 'FAILED') NOT NULL DEFAULT 'PENDING',`uploadedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL, INDEX `Document_companyId_idx`(`companyId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Application` (`id` VARCHAR(191) NOT NULL,`tenderId` VARCHAR(191) NOT NULL,`companyId` VARCHAR(191) NOT NULL,`complianceScore` INTEGER NOT NULL DEFAULT 0,`status` ENUM('UNDER_REVIEW', 'ACCEPTED', 'REJECTED') NOT NULL DEFAULT 'UNDER_REVIEW',`rejectionReason` VARCHAR(191) NULL,`submittedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL, INDEX `Application_companyId_idx`(`companyId`), UNIQUE INDEX `Application_tenderId_companyId_key`(`tenderId`, `companyId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ApplicationDocument` (`id` VARCHAR(191) NOT NULL,`applicationId` VARCHAR(191) NOT NULL,`documentId` VARCHAR(191) NOT NULL,`requirementId` VARCHAR(191) NULL, UNIQUE INDEX `ApplicationDocument_applicationId_documentId_requirementId_key`(`applicationId`, `documentId`, `requirementId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ComplianceResult` (`id` VARCHAR(191) NOT NULL,`applicationId` VARCHAR(191) NOT NULL,`requirementId` VARCHAR(191) NOT NULL,`result` ENUM('PASS', 'FAIL', 'REVIEW') NOT NULL,`remarks` VARCHAR(191) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `ComplianceResult_applicationId_requirementId_key`(`applicationId`, `requirementId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Notification` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`title` VARCHAR(191) NOT NULL,`message` VARCHAR(191) NOT NULL,`type` ENUM('APPLICATION_SUBMITTED', 'APPLICATION_ACCEPTED', 'APPLICATION_REJECTED', 'BLACKLISTED', 'NEW_BID', 'DOCUMENT_REVIEW') NOT NULL,`read` BOOLEAN NOT NULL DEFAULT false,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `Notification_userId_read_idx`(`userId`, `read`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `RefreshToken` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`tokenHash` VARCHAR(191) NOT NULL,`expiresAt` DATETIME(3) NOT NULL,`revoked` BOOLEAN NOT NULL DEFAULT false,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `RefreshToken_tokenHash_key`(`tokenHash`), INDEX `RefreshToken_userId_revoked_idx`(`userId`, `revoked`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `OfficerProfile` ADD CONSTRAINT `OfficerProfile_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
