ALTER TABLE `ApplicationDocument` ADD CONSTRAINT `ApplicationDocument_applicationId_fkey` FOREIGN KEY (`applicationId`) REFERENCES `Application`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `ApplicationDocument` ADD CONSTRAINT `ApplicationDocument_documentId_fkey` FOREIGN KEY (`documentId`) REFERENCES `Document`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `ApplicationDocument` ADD CONSTRAINT `ApplicationDocument_requirementId_fkey` FOREIGN KEY (`requirementId`) REFERENCES `TenderRequirement`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
